import pandas as pd
import joblib
from sklearn.ensemble import RandomForestClassifier

print("🧠 Training your AI model on your authentic tracks...")

try:
    # 1. Load your local dataset spreadsheet generated by create_dataset.py
    data = pd.read_csv("mix_dataset.csv")
    X = data.drop("label", axis=1)  # Mathematical metrics (low, mid, high numbers)
    y = data["label"]  # Category answers (0)

    # 2. Fit the machine learning model
    model = RandomForestClassifier(n_estimators=100, random_state=42)
    model.fit(X, y)

    # 3. Serialize your AI brain model into a physical file
    joblib.dump(model, "mixing_ai_model.pkl")
    print("🎉 SUCCESS! 'mixing_ai_model.pkl' created using your 8 real files.")

except FileNotFoundError:
    print("❌ Error: Could not find 'mix_dataset.csv'.")
    print("Please run 'python create_dataset.py' in your terminal first to generate your spreadsheet!")
except Exception as e:
    print(f"❌ An error occurred during training: {e}")
